import { useMemo } from 'react';

import { useBffData, useCurrentPage, usePageFilterStatus } from 'hooks';

import type {
  InnovationHubPortfolioDataResult,
  PortfolioCardData,
  PortfolioPieChartData,
} from '../../types';

const BFF_VIEW_ID = 'innovation_innovation-hub_overview';
const PORTFOLIO_BIG_NUMBERS_COMPONENT_ID =
  'innovation-hub-overview-portfolio-big-numbers';
const PORTFOLIO_PIE_CHARTS_COMPONENT_ID =
  'innovation-hub-overview-portfolio-pie-charts';

const isRecord = (value: unknown): value is Record<string, unknown> =>
  value != null && typeof value === 'object';

function getPortfolioArray<T>(
  data: unknown,
  componentId: string,
  dataKey: string,
): T[] {
  if (!isRecord(data)) return [];

  const componentData = data[componentId];
  const nestedData = isRecord(componentData)
    ? componentData[dataKey]
    : undefined;

  if (Array.isArray(nestedData)) {
    return nestedData as T[];
  }

  const flatData = data[dataKey];

  return Array.isArray(flatData) ? (flatData as T[]) : [];
}

export function useInnovationHubPortfolioData(): InnovationHubPortfolioDataResult {
  const { currentPage } = useCurrentPage();
  const { isLoading: filtersLoading } = usePageFilterStatus(currentPage);
  const bffResult = useBffData({
    id: BFF_VIEW_ID,
    kpiGroup: 'innovation',
    skipRequest: filtersLoading,
  });

  const portfolioData = useMemo(
    () => ({
      bigNumbers: getPortfolioArray<PortfolioCardData>(
        bffResult.data,
        PORTFOLIO_BIG_NUMBERS_COMPONENT_ID,
        'portfolio-big-numbers',
      ),
      pieCharts: getPortfolioArray<PortfolioPieChartData>(
        bffResult.data,
        PORTFOLIO_PIE_CHARTS_COMPONENT_ID,
        'portfolio-pie-charts',
      ),
    }),
    [bffResult.data],
  );

  return {
    ...portfolioData,
    loading: bffResult.loading,
    error: bffResult.error,
  };
}
